"""
    Extract ID from the end of the URI

    Args:
        id_or_uri: ID or URI of the OneView resources.

    Returns:
        str: The string founded after the last "/"
    """
def extract_id_from_uri(id_or_uri: Any) -> object {
    if ('/' in id_or_uri) {
        return id_or_uri[(id_or_uri.rindex('/') + 1):];
    } else {
        return id_or_uri;
    }
}

"""
    :type timeSeries: List[int]
    :type duration: int
    :rtype: int
    """
def findPoisonedDuration(timeSeries: Any, duration: Any) -> object {
    n = len(timeSeries);
    if (n == 0) {
        return 0;
    }
    head = 0;
    totalTime = 0;
    for i in range(1, n) {
        d = timeSeries[i] - timeSeries[(i - 1)];
        if (d > duration) {
            totalTime += (timeSeries[(i - 1)] - timeSeries[head]) + duration;
            head = i;
        }
    }
    totalTime += (timeSeries[(n - 1)] - timeSeries[head]) + duration;
    return totalTime;
}

